import { afterEach, describe, expect, test } from 'vitest';
import {
  deleteGlobalConfig,
  parse,
  parseAsync,
  safeParse,
  safeParseAsync,
  setGlobalConfig,
} from '../index.ts';
import { number, object, objectAsync, string, union } from '../schemas/index.ts';

describe('hideInput', () => {
  afterEach(() => {
    deleteGlobalConfig();
  });

  test('redacts issues and preserves explicit false overrides', () => {
    setGlobalConfig({ hideInput: true });

    expect(safeParse(string(), 123).issues?.[0].input).toBeUndefined();
    expect(safeParse(string(), 123, { hideInput: false }).issues?.[0].input).toBe(
      123
    );
    expect(safeParse(string(), 123, { hideInput: true }).issues?.[0].input).toBe(
      undefined
    );
  });

  test('redacts nested and union issue inputs', () => {
    const result = safeParse(
      object({ value: union([string(), number()]) }),
      { value: true },
      { hideInput: true }
    );

    const visit = (issue: { input: unknown; issues?: unknown[] }) => {
      expect(issue.input).toBeUndefined();
      issue.issues?.forEach((child) => visit(child as typeof issue));
    };
    result.issues?.forEach((issue) => visit(issue));
  });

  test('message callbacks receive original input before redaction', () => {
    let seen: unknown;
    const result = safeParse(
      string((issue) => {
        seen = issue.input;
        return 'custom';
      }),
      123,
      { hideInput: true }
    );

    expect(seen).toBe(123);
    expect(result.issues?.[0]).toMatchObject({
      input: undefined,
      received: '123',
      message: 'custom',
    });
  });

  test('supports async parsing and leaves successful output unchanged', async () => {
    const result = await safeParseAsync(
      objectAsync({ a: string(), b: number() }),
      { a: 1, b: 'two' },
      { hideInput: true }
    );

    expect(result.issues).toHaveLength(2);
    result.issues?.forEach((issue) => expect(issue.input).toBeUndefined());
    expect(await parseAsync(objectAsync({ a: string() }), { a: 'ok' }, { hideInput: true })).toEqual({
      a: 'ok',
    });
  });

  test('does not alter successful sync parsing or default issue inputs', () => {
    expect(parse(string(), 'ok', { hideInput: true })).toBe('ok');
    expect(safeParse(string(), 123).issues?.[0].input).toBe(123);
  });
});
