export interface Config<TIssue extends BaseIssue<unknown>> {
  /**
   * The selected language.
   */
  readonly lang?: string | undefined;
  /**
   * The error message.
   */
  readonly message?: ErrorMessage<TIssue> | undefined;
  /**
   * Whether it should be aborted early.
   */
  readonly abortEarly?: boolean | undefined;
  /**
   * Whether a pipe should be aborted early.
   */
  readonly abortPipeEarly?: boolean | undefined;
  /**
   * Whether the input should be hidden in issues.
   */
  readonly hideInput?: boolean | undefined;
}

{
  lang: config?.lang ?? store?.lang,
  message: config?.message,
  abortEarly: config?.abortEarly ?? store?.abortEarly,
  abortPipeEarly: config?.abortPipeEarly ?? store?.abortPipeEarly,
  ...(config?.hideInput ?? store?.hideInput) !== undefined
    ? { hideInput: config?.hideInput ?? store?.hideInput }
    : {},
}

export interface Config<TIssue extends BaseIssue<unknown>> {
  /**
   * The selected language.
   */
  readonly lang?: string | undefined;
  /**
   * The error message.
   */
  readonly message?: ErrorMessage<TIssue> | undefined;
  /**
   * Whether it should be aborted early.
   */
  readonly abortEarly?: boolean | undefined;
  /**
   * Whether a pipe should be aborted early.
   */
  readonly abortPipeEarly?: boolean | undefined;
  /**
   * Whether the input should be hidden in issues.
   */
  readonly hideInput?: boolean | undefined;
}

{
  // Hint: The configuration is deliberately not constructed with the spread
  // operator for performance reasons
  return {
    lang: config?.lang ?? store?.lang,
    message: config?.message,
    abortEarly: config?.abortEarly ?? store?.abortEarly,
    abortPipeEarly: config?.abortPipeEarly ?? store?.abortPipeEarly,
    ...(config?.hideInput ?? store?.hideInput) !== undefined
      ? { hideInput: config?.hideInput ?? store?.hideInput }
      : {},
  };
}

{
  // Get expected and received string
  const input = other && 'input' in other ? other.input : dataset.value;
  const expected = other?.expected ?? context.expects ?? null;
  const received = other?.received ?? _stringify(input);

  // Create issue object
  // Hint: The issue is deliberately not constructed with the spread operator
  // for performance reasons
  const issue: BaseIssue<unknown> = {
    kind: context.kind,
    type: context.type,
    input,
    expected,
    received,
    message: `Invalid ${label}: ${
      expected ? `Expected ${expected} but r` : 'R'
    }eceived ${received}`,
    requirement: context.requirement,
    path: other?.path,
    issues: other?.issues,
    lang: config.lang,
    abortEarly: config.abortEarly,
    abortPipeEarly: config.abortPipeEarly,
  };

  // Check if context is a schema
  const isSchema = context.kind === 'schema';

  // Get custom issue message
  const message =
    other?.message ??
    context.message ??
    getSpecificMessage(context.reference, issue.lang) ??
    (isSchema ? getSchemaMessage(issue.lang) : null) ??
    config.message ??
    getGlobalMessage(issue.lang);

  // If custom message if specified, override default message
  if (message !== undefined) {
    // @ts-expect-error
    issue.message =
      typeof message === 'function'
        ? // @ts-expect-error
          message(issue)
        : message;
  }

  // Hide the issue input after message callbacks have received it.
  if (config.hideInput) {
    // @ts-expect-error
    issue.input = undefined;
  }

  // If context is a schema, set typed to `false`
  if (isSchema) {
    dataset.typed = false;
  }

  // Add issue to dataset
  if (dataset.issues) {
    dataset.issues.push(issue);
  } else {
    // @ts-expect-error
    dataset.issues = [issue];
  }
}

export function fallback<
  const TSchema extends BaseSchema<unknown, unknown, BaseIssue<unknown>>,
  const TFallback extends Fallback<TSchema>,
>(
  schema: TSchema,
  fallback: TFallback,
  predicate?: FallbackPredicate<TSchema>
): SchemaWithFallback<TSchema, TFallback> {
  return {
    ...schema,
    fallback,
    get '~standard'() {
      return _getStandardProps(this);
    },
    '~run'(dataset, config) {
      const outputDataset = schema['~run'](dataset, config);
      return outputDataset.issues &&
        (!predicate || predicate(outputDataset, config))
        ? { typed: true, value: getFallback(this, outputDataset, config) }
        : outputDataset;
    },
  };
}

export function fallbackAsync<
  const TSchema extends
    | BaseSchema<unknown, unknown, BaseIssue<unknown>>
    | BaseSchemaAsync<unknown, unknown, BaseIssue<unknown>>,
  const TFallback extends FallbackAsync<TSchema>,
>(
  schema: TSchema,
  fallback: TFallback,
  predicate?: FallbackPredicateAsync<TSchema>
): SchemaWithFallbackAsync<TSchema, TFallback> {
  return {
    ...schema,
    fallback,
    async: true,
    get '~standard'() {
      return _getStandardProps(this);
    },
    async '~run'(dataset, config) {
      const outputDataset = await schema['~run'](dataset, config);
      if (outputDataset.issues) {
        if (!predicate || (await predicate(outputDataset, config))) {
          return {
            typed: true,
            value: await getFallback(this, outputDataset, config),
          };
        }
      }
      return outputDataset;
    },
  };
}

